}

interfaces.res_body:
{
  "type": "object",
  "properties": {
    "data": {
      "type": "object",
      "properties": {
        "hasSegmentData": {
          "type": "boolean",
          "example": false,
          "description": "是否存在段表数据（false=老数据仅纯文本全文，speakers 为空，前端隐藏入口）"
        },
        "hasTimestamp": {
          "type": "boolean",
          "example": false,
          "description": "是否存在有效时间戳（false=段无起止时间，segments/ratio 不可用）"
        },
        "speakers": {
          "type": "array",
          "description": "发言人列表（按首次发言顺序，末尾为手动新建的 0 段发言人）；无段数据或无说话人标识时为空列表",
          "items": {
            "type": "object",
            "properties": {
              "chars": {
                "type": "integer",
                "format": "int64",
                "description": "总字数"
              },
              "name": {
                "type": "string",
                "description": "显示名：已改名取发言人档案，未改名默认\"发言人N\"（N 按首次出现序）"
              },
              "ratio": {
                "type": "number",
                "format": "double",
                "description": "时长占比（0-1，= 该人发言时长/会议总时长；无时间戳时为 0）"
              },
              "segments": {
                "type": "array",
                "description": "发声时段（毫秒，相邻间隔<1s 已合并；供进度条渲染与 Seek）",
                "items": {
                  "type": "object",
                  "properties": {
                    "endMs": {
                      "type": "integer",
                      "format": "int64",
                      "description": "结束毫秒（相对会议开始）"
                    },
                    "startMs": {
                      "type": "integer",
                      "format": "int64",
                      "description": "起始毫秒（相对会议开始）"
                    }
                  },
                  "$$ref": "#/definitions/发声时段"
                }
              },
              "speakerId": {
                "type": "string",
                "description": "发言人 ID（ASR 输出原始 ID 如 0/1；手动新建为 manual- 前缀）"
              },
              "turns": {
                "type": "integer",
                "format": "int32",
                "description": "句段数"
              },
              "userId": {
                "type": "string",
                "description": "绑定的企业用户ID（通讯录选人后有值，前端据此渲染真实头像）"
              }
            },
            "$$ref": "#/definitions/发言人画像项"
          }
        }
      },
      "$$ref": "#/definitions/发言人画像响应"
    },
    "error": {
      "type": "string"
    },
    "errorCode": {
      "type": "integer",
      "format": "int32"
    },
    "success": {
      "type": "boolean"
    },
    "timestamp": {
      "type": "integer",
      "format": "int64"
    }
  },
  "$$ref": "#/definitions/Result«发言人画像响应»"
}

